from microbit import *
import random

while True:
    if button_a.was_pressed():
        number = random.randint(1, 6)
        if number == 1:
            display.scroll("READ")
        elif number == 2:
            display.scroll("DRAW")

    elif number == 3:
        display.scroll("WALK")
    elif number == 4:
        display.scroll("MUSIC")
    elif number == 5:
        display.scroll("PUZZLE")
